select r.id,r.slug,r.name,r.description,r.method,r.meal_role,r.is_complete_meal,r.primary_protein,r.base_servings,r.total_time_minutes,r.diet,r.flavor,(select jsonb_agg(jsonb_build_object('step_no',s.step_no,'text',s.text) order by s.step_no) from public.recipe_steps s where s.recipe_id=r.id) as steps,(select jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'quantity',trim_scale(ri.quantity),'unit',u.code,'note',ri.prep_note,'optional',ri.is_optional) order by i.id) from public.recipe_ingredients ri join public.ingredients i on i.id=ri.ingredient_id left join public.units u on u.id=ri.unit_id where ri.recipe_id=r.id) as ingredients from public.recipes r where r.is_public=true
